INSERT OR IGNORE INTO `jobs` (`id`, `company`, `position`, `department`, `category`, `location`, `recruitment_type`, `description`, `requirements`, `job_url`, `normalized_url`, `source`, `source_job_id`, `published_date`, `deadline`, `tags`, `raw_text`, `company_intro`, `interview_experience`, `written_test_materials`, `common_questions`, `preparation_notes`, `is_draft`, `import_batch_id`, `created_at`, `updated_at`) VALUES
